// 17 — Preparar datos para CRM (NO cortar el flujo si hay respuesta del bot)
function safe(name) {
  try {
    return $(name).first().json || {};
  } catch (e) {
    return {};
  }
}

const wh = safe('01 Entrada | Webhook Chatwoot');
const body = wh.body || wh || {};
const r25 = safe('25 Sistema | Memoria + Contexto');
const p15 = safe('15b Sistema | Preparar envío WhatsApp');
const p14g = safe('14g Sistema | Restaurar salida tras acción');
let p14d = {};
try {
  p14d = $('14d Sistema | Adaptar salida LUNA v3').first().json || {};
} catch (e) {}

const original = String(
  body.content ||
    wh.content ||
    r25.user_message ||
    $json.original_message ||
    $json.user_message ||
    ''
).trim();

const ai = String(
  p15.final_reply ||
    p15.wa_part1 ||
    p14g.final_reply ||
    p14d.final_reply ||
    $json.final_reply ||
    $json.ai_response ||
    ''
).trim();

// Si no hay respuesta del bot, no hay nada que guardar
if (!ai) {
  // intentar una última vez con $json de la rama actual
  const fallbackAi = String($json.wa_part1 || $json.content || '').trim();
  if (!fallbackAi) return [];
}

const finalAi = ai || String($json.wa_part1 || $json.content || '').trim();
const finalOrig = original || String(r25.user_message || '[msg]').trim() || '[msg]';

const conversation_id = String(
  body.conversation?.id ||
    body.conversation_id ||
    r25.conversation_id ||
    p14d.conversation_id ||
    $json.conversation_id ||
    ''
);

const phone =
  body.conversation?.meta?.sender?.phone_number ||
  body.sender?.phone_number ||
  r25.phone ||
  '';

return [
  {
    json: {
      ...$json,
      ...p15,
      original_message: finalOrig,
      user_message: finalOrig,
      ai_response: finalAi,
      final_reply: finalAi,
      conversation_id,
      phone: String(phone || ''),
      valid_message: true,
      valid: true,
      known_name: p14d.known_name || p15.known_name || r25.known_name || $json.known_name || '',
      known_email: p14d.known_email || p15.known_email || r25.known_email || $json.known_email || '',
      business_type: p14d.business_type || r25.business_type || $json.business_type || '',
      intent: p14d.intent || $json.intent || r25.router_intent || '',
    },
  },
];

// === LUNA_CORE_BEGIN ===
// Fuente única de precios, copy y helpers. Edita aquí y corre:
//   node scripts/_sync_luna_core.js
// No usa $() de n8n — solo JS puro.

var LUNA = typeof LUNA !== 'undefined' ? LUNA : {};

var CATALOG_CONTEXT = $('25 Sistema | Memoria + Contexto').first().json || {};
var CATALOG_PACKAGES = CATALOG_CONTEXT.catalog_packages || {};
var CATALOG_ESSENTIAL = CATALOG_PACKAGES['PKG-ESSENTIAL'] || {};
var CATALOG_PROFESSIONAL = CATALOG_PACKAGES['PKG-PROFESSIONAL'] || {};
if (!CATALOG_CONTEXT.catalog_ready || !Number(CATALOG_ESSENTIAL.price_project) || !Number(CATALOG_PROFESSIONAL.price_project)) { throw new Error('Catálogo dinámico no disponible o incompleto'); }

LUNA.CONFIG = {
  brand: 'Luenio',
  assistant: 'Luna',
  site: 'https://luenio.com',
  tz: 'America/Bogota',
  bizDays: [1, 2, 3, 4, 5],
  bizStart: 8,
  bizEnd: 18,
  fuStart: 8,
  fuEnd: 20,
};

LUNA._money = function (n) {
  return '$' + Number(n).toLocaleString('es-CO');
};

LUNA._catalogContext = function () {
  try {
    if (typeof CATALOG_CONTEXT !== 'undefined' && CATALOG_CONTEXT) return CATALOG_CONTEXT;
  } catch (e) {}
  return {};
};

LUNA._catalogPackage = function (sku) {
  var c = LUNA._catalogContext();
  var packages = c.catalog_packages || {};
  var priceMap = c.catalog_price_map || {};
  var raw = packages[sku] || {};
  var mapped = priceMap[sku] || {};
  return {
    sku: sku,
    name: String(raw.name || (sku === 'PKG-ESSENTIAL' ? 'Esencial' : 'Profesional')),
    price_project: Number(raw.price_project || mapped.project || 0),
    price_monthly: Number(raw.price_monthly || mapped.monthly || 0),
  };
};

LUNA.catalogReady = function () {
  var c = LUNA._catalogContext();
  var e = LUNA._catalogPackage('PKG-ESSENTIAL');
  var p = LUNA._catalogPackage('PKG-PROFESSIONAL');
  return c.catalog_ready === true && e.price_project > 0 && p.price_project > 0;
};

LUNA.priceLines = function () {
  var e = LUNA._catalogPackage('PKG-ESSENTIAL');
  var p = LUNA._catalogPackage('PKG-PROFESSIONAL');
  var m = LUNA._money;
  var eMonthly = e.price_monthly > 0 ? ' + *' + m(e.price_monthly) + '/mes*' : '';
  var pMonthly = p.price_monthly > 0 ? ' + *' + m(p.price_monthly) + '/mes*' : '';
  var essential = '*' + e.name + '*: desde *' + m(e.price_project) + '*' + eMonthly;
  var professional = '*' + p.name + '*: desde *' + m(p.price_project) + '*' + pMonthly;
  return {
    essential: m(e.price_project),
    essentialMonth: e.price_monthly > 0 ? m(e.price_monthly) : '',
    professional: m(p.price_project),
    professionalMonth: p.price_monthly > 0 ? m(p.price_monthly) : '',
    essentialLine: essential,
    professionalLine: professional,
    short: essential + ' · ' + professional,
    block: '📦 ' + essential + '\n🚀 ' + professional + '\n🌐 Dominio: se cotiza aparte según disponibilidad.',
    scope: 'Si quieres solo web o solo chatbot, también es posible; el valor se confirma según el alcance y las integraciones.',
  };
};

LUNA.greetingHourBogota = function () {
  try {
    var h = Number(
      new Intl.DateTimeFormat('en-US', {
        timeZone: LUNA.CONFIG.tz,
        hour: 'numeric',
        hour12: false,
      }).format(new Date())
    );
    if (h >= 5 && h < 12) return 'Buenos días';
    if (h >= 12 && h < 19) return 'Buenas tardes';
    return 'Buenas noches';
  } catch (e) {
    return 'Hola';
  }
};

LUNA.bogotaParts = function (d) {
  var fmt = new Intl.DateTimeFormat('en-US', {
    timeZone: LUNA.CONFIG.tz,
    weekday: 'short',
    hour: 'numeric',
    minute: 'numeric',
    hour12: false,
  });
  var parts = fmt.formatToParts(d || new Date());
  var map = {};
  for (var i = 0; i < parts.length; i++) map[parts[i].type] = parts[i].value;
  var wd = String(map.weekday || '').toLowerCase();
  var dayMap = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
  var day = dayMap[wd] != null ? dayMap[wd] : new Date().getDay();
  var hour = Number(map.hour === '24' ? 0 : map.hour);
  var minute = Number(map.minute || 0);
  return { day: day, hour: hour, minute: minute };
};

LUNA.isBusinessHours = function (d) {
  var p = LUNA.bogotaParts(d);
  if (LUNA.CONFIG.bizDays.indexOf(p.day) < 0) return false;
  var mins = p.hour * 60 + p.minute;
  return mins >= LUNA.CONFIG.bizStart * 60 && mins < LUNA.CONFIG.bizEnd * 60;
};

LUNA.nextBusinessOpenLabel = function () {
  var now = new Date();
  var start = LUNA.CONFIG.bizStart;
  for (var add = 0; add < 8; add++) {
    var probe = new Date(now.getTime() + add * 24 * 3600 * 1000);
    var day = LUNA.bogotaParts(probe).day;
    if (LUNA.CONFIG.bizDays.indexOf(day) >= 0) {
      if (add === 0 && LUNA.isBusinessHours(now)) return 'ahora';
      if (add === 0) {
        var hh = LUNA.bogotaParts(now).hour;
        if (hh < start) return 'hoy a las ' + String(start).padStart(2, '0') + ':00 (hora Colombia)';
      }
      if (add === 1) return 'mañana a las ' + String(start).padStart(2, '0') + ':00 (hora Colombia)';
      var names = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
      return names[day] + ' a las ' + String(start).padStart(2, '0') + ':00 (hora Colombia)';
    }
  }
  return 'el próximo día hábil a las ' + String(start).padStart(2, '0') + ':00 (hora Colombia)';
};

LUNA.normMsg = function (s) {
  return String(s || '')
    .normalize('NFKC')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/[!¡?.…,;:]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
};

LUNA.isMenuRequest = function (lower) {
  var t = LUNA.normMsg(lower);
  if (!t) return false;
  if (/^(menu|menú|opciones|opcion|opción|ayuda|ops)$/i.test(t)) return true;
  if (/(^|\s)(ver|dame|mostrar|abre|abrir|quiero|necesito)?\s*(el\s+)?(menu|menú)(\s|$)/i.test(t)) return true;
  return false;
};

LUNA.isMenuDigit = function (lower) {
  // SOLO menú real: "1", "2.", "3)" o "1 pack" corto.
  // NUNCA "1. vendo por WhatsApp y me demoro..." (respuesta de discovery)
  var t = LUNA.normMsg(lower);
  if (!t) return '';
  if (t.length > 36) return '';
  if (/^([1-5])$/.test(t)) return t.charAt(0);
  if (/^([1-5])\s*[-.)]\s*$/.test(t)) return t.charAt(0);
  var m = t.match(/^([1-5])\s+(pack|precios?|propuesta|asesor|reset|web|chatbot|menu|menú)\b/);
  return m ? m[1] : '';
};

LUNA.isPlaceholderEmail = function (em) {
  var e = String(em || '').toLowerCase().trim();
  if (!e || e.indexOf('@') < 0) return true;
  var parts = e.split('@');
  var local = parts[0] || '';
  var domain = parts[1] || '';
  // Solo basura obvia de copy o ejemplos; no bloquear direcciones sintácticamente válidas.
  var fakeLocalExact = {
    nombre: 1,
    ejemplo: 1,
    example: 1,
    test: 1,
    prueba: 1,
    usuario: 1,
    user: 1,
    mail: 1,
    email: 1,
    correo: 1,
    demo: 1,
    sample: 1,
    asd: 1,
    abc: 1,
    xxx: 1,
    noreply: 1,
    'no-reply': 1,
    tucorreo: 1,
    tu_correo: 1,
    yourname: 1,
    'your.email': 1,
  };
  if (fakeLocalExact[local]) return true;
  // dominios claramente de documentación
  if (/^(example\.com|test\.com|email\.com|dominio\.com|tuempresa\.com|localhost)$/i.test(domain)) return true;
  // Local y dominio ambos genéricos.
  if (local === 'correo' || local === 'email' || local === 'mail') return true;
  if (local.length < 1) return true;
  return false;
};

/** Extrae email aunque venga dentro de una frase. */
LUNA.extractRealEmail = function (text) {
  var m = String(text || '').match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i);
  if (!m) return '';
  return LUNA.isPlaceholderEmail(m[0]) ? '' : m[0];
};

LUNA._NAME_STOP = {
  hola: 1, buenas: 1, buen: 1, quiero: 1, necesito: 1, info: 1, precio: 1, precios: 1,
  web: 1, chatbot: 1, bot: 1, servicio: 1, servicios: 1, pack: 1, perfecto: 1, genial: 1,
  listo: 1, ok: 1, dale: 1, claro: 1, si: 1, los: 1, las: 1, el: 1, la: 1, un: 1, una: 1,
  mi: 1, me: 1, te: 1, se: 1, para: 1, con: 1, por: 1, de: 1, del: 1, al: 1, y: 1, o: 1,
  correo: 1, email: 1, mail: 1, nombre: 1, soy: 1, estoy: 1, tengo: 1, nada: 1, gracias: 1,
  hey: 1, hi: 1, hello: 1, ambos: 1, dos: 1, tres: 1, '1': 1, '2': 1, '3': 1, propuesta: 1,
  gmail: 1, pc: 1, pcs: 1, venta: 1, ventas: 1, negocio: 1,
};

LUNA.titleCaseName = function (s) {
  return String(s || '')
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map(function (p) {
      return p.charAt(0).toUpperCase() + p.slice(1).toLowerCase();
    })
    .join(' ');
};

LUNA.isNameToken = function (t) {
  var w = String(t || '').trim();
  if (w.length < 2 || w.length > 22) return false;
  if (/\d/.test(w)) return false;
  if (LUNA._NAME_STOP[w.toLowerCase()]) return false;
  if (!/^[A-Za-záéíóúÁÉÍÓÚñÑüÜ'-]+$/.test(w)) return false;
  return true;
};

LUNA.isValidPersonName = function (n) {
  var s = String(n || '').trim();
  if (!s || s.length < 2 || s.length > 50) return false;
  if (/@|http|www\./i.test(s)) return false;
  if (/\d/.test(s)) return false;
  var parts = s.split(/\s+/).filter(Boolean);
  if (!parts.length || parts.length > 4) return false;
  for (var i = 0; i < parts.length; i++) if (!LUNA.isNameToken(parts[i])) return false;
  return true;
};

LUNA.sanitizeName = function (n) {
  var s = String(n || '')
    .trim()
    .replace(/[^a-zA-ZáéíóúÁÉÍÓÚñÑüÜ\s'-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!s || s.length < 2 || /\d/.test(s) || s.split(/\s+/).length > 4) return '';
  var parts = s.split(/\s+/);
  for (var i = 0; i < parts.length; i++) {
    if (LUNA._NAME_STOP[parts[i].toLowerCase()]) return '';
  }
  if (/propuesta|enviame|gmail|correo/i.test(s)) return '';
  var t = LUNA.titleCaseName(s);
  return LUNA.isValidPersonName(t) ? t : '';
};

LUNA.extractNameFromText = function (text, emailInMsg) {
  var raw = String(text || '').trim();
  if (!raw) return '';
  var n = '';
  if (/mi nombre es/i.test(raw)) n = raw.split(/mi nombre es/i)[1];
  else if (/me llamo/i.test(raw)) n = raw.split(/me llamo/i)[1];
  else if (/\bnombre\s*[:=]/i.test(raw)) n = raw.split(/\bnombre\s*[:=]/i)[1];
  else if (/^soy\s+[a-záéíóúñ]/i.test(raw) && raw.length < 40 && !/luna|bot|ia|asistente/i.test(raw)) {
    n = raw.replace(/^soy\s+/i, '');
  }
  if (n) n = n.split(/y mi correo|y el correo|correo|email|mail|,|\.|$| y |\n|@| para | por /i)[0].trim();
  if (!n && emailInMsg) {
    var left = raw
      .replace(emailInMsg, ' ')
      .replace(/\b(correo|email|mail|env[ií]a(?:me)?|m[aá]nda(?:me)?|perfecto|genial|listo|ok|dale|claro|sí|si|por\s*favor)\b/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    if (left.split(/\s+/).length <= 3) n = left;
  }
  return LUNA.sanitizeName(n);
};

LUNA.isOptOutMessage = function (text) {
  var t = String(text || '').toLowerCase().trim();
  if (!t) return false;
  if (/^(stop|baja|unsubscribe)$/i.test(t)) return true;
  if (/no me (escriban|escribas|molesten|moleste)|no molestar|no quiero (mas|más) mensajes|dejen de escribir|cancelar (mensajes|seguimiento)/i.test(t)) return true;
  if (/^no gracias$|^no,? gracias$/i.test(t) && t.length < 20) return true;
  return false;
};

LUNA.detectRubro = function (text) {
  var t = String(text || '').toLowerCase();
  if (!t.trim()) return '';
  if (/\bpc\b|\bpcs\b|computador|hardware|perif[eé]rico|armar\s*pc|builds|vendo\s*pcs?|venta\s*de\s*pcs?|partes\s*de\s*pc/i.test(t)) return 'pcs';
  if (/inmobil|arriendo|apartament|casa en venta|finca ra[ií]z|propiedades/i.test(t)) return 'inmobiliaria';
  if (/restaurant|comida|men[uú] digital|pedidos|delivery|cafeter[ií]a/i.test(t)) return 'restaurante';
  if (/tienda|retail|ropa|zapatos|cat[aá]logo de productos|vendo productos|e-?commerce/i.test(t)) return 'retail';
  if (/servicio|consultor|cl[ií]nica|dental|est[eé]tica|abogad|taller mec[aá]nico|peluquer|tecnolog[ií]a|software|startup|saas|agencia/i.test(t)) return 'servicios';
  if (/automatiz/i.test(t)) return 'automatizacion';
  return '';
};

LUNA.rubroLabel = function (code) {
  var m = {
    pcs: 'venta de PCs / hardware',
    retail: 'tienda / retail',
    servicios: 'negocio de servicios',
    inmobiliaria: 'inmobiliaria',
    restaurante: 'restaurante / local de comida',
    automatizacion: 'automatizaciones',
  };
  return m[code] || 'tu negocio';
};

LUNA.solutionForRubro = function (code) {
  if (code === 'pcs') return 'Pack: web catálogo + cotizador + chatbot WhatsApp';
  if (code === 'retail') return 'Pack: catálogo web + chatbot WhatsApp';
  if (code === 'servicios') return 'Pack: web de confianza + chatbot que califica leads';
  if (code === 'inmobiliaria') return 'Pack: fichas web + chatbot que califica leads';
  if (code === 'restaurante') return 'Web/menú + WhatsApp según alcance';
  return 'Pack web + chatbot de WhatsApp';
};

LUNA.detectUrgency = function (text) {
  var t = String(text || '').toLowerCase();
  if (/urgente|lo necesito ya|esta semana|inmediato|ya mismo/i.test(t)) return 'ya';
  if (/este mes|pr[oó]ximas semanas|en (unos )?d[ií]as/i.test(t)) return 'este_mes';
  if (/solo miro|estoy viendo|m[aá]s adelante|explor|averiguando/i.test(t)) return 'explorando';
  return '';
};

LUNA.detectDecisionRole = function (text) {
  var t = String(text || '').toLowerCase();
  if (/soy el due[nñ]o|soy due[nñ]o|somos due[nñ]os|mi empresa|tengo el negocio/i.test(t)) return 'dueño';
  if (/socio|somos socios|mi socio/i.test(t)) return 'socio';
  if (/trabajo en|soy empleado|me mandaron|mi jefe/i.test(t)) return 'empleado';
  return '';
};

LUNA.detectBudgetSignal = function (text) {
  var t = String(text || '').toLowerCase();
  if (/presupuesto apretado|muy caro|barato|econ[oó]mico|poco presupuesto/i.test(t)) return 'bajo';
  if (/invierto|presupuesto amplio|lo que cueste|premium/i.test(t)) return 'alto';
  if (/presupuesto medio|est[aá]ndar/i.test(t)) return 'medio';
  return '';
};

LUNA.nextPipelineStage = function (ctx) {
  if (ctx.opt_out) return 'cerrado';
  if (ctx.handoff || ctx.human_required) return 'handoff';
  if (ctx.proposal_sent) return 'propuesta';
  if (ctx.business_type && ctx.project_goal) return 'calificado';
  if (ctx.business_type || ctx.project_goal) return 'descubrimiento';
  return 'nuevo';
};

LUNA.handoffMessage = function (name) {
  var n = name ? ', ' + name : '';
  var open = LUNA.isBusinessHours(new Date());
  var hoursLine =
    '🕐 Horario: *lun–vie ' +
    LUNA.CONFIG.bizStart +
    ':00 a. m. – ' +
    LUNA.CONFIG.bizEnd +
    ':00 p. m.* (Colombia)';
  if (open) {
    return (
      'Con gusto' +
      n +
      ' 🤝\n\n' +
      'Te paso con un *asesor humano* en este chat.\n' +
      '✅ *En horario*: en un momento te escriben.\n\n' +
      hoursLine +
      '\n\nVolver conmigo: *activar luna* 🌙'
    );
  }
  return (
    'Con gusto' +
    n +
    ' 🤝\n\n' +
    'Dejé tu charla para un *asesor humano*.\n' +
    '🌙 *Fuera de horario* — no hace falta que esperes en línea.\n' +
    'Te escriben el próximo hábil desde las *' +
    String(LUNA.CONFIG.bizStart).padStart(2, '0') +
    ':00 a. m.*\n\n' +
    hoursLine +
    '\n\nSeguir conmigo: *activar luna* 💬'
  );
};

/** 1 sola pregunta curiosa por rubro — ANTES de precios (Sprint B) */
LUNA.buildDiscoveryQuestion = function (code, name) {
  var n = name ? ', ' + name : '';
  if (code === 'pcs') {
    return (
      'Buenísimo' +
      n +
      ' 💻 *PCs / hardware*.\n\n' +
      'Para no darte algo genérico: ¿qué te frena más hoy — *cotizar lento*, *no dar abasto en WhatsApp*, o que el cliente *no ve catálogo claro*?'
    );
  }
  if (code === 'retail') {
    return (
      'Perfecto' +
      n +
      ' 👗 *Tienda / retail*.\n\n' +
      '¿Qué te duele más ahora: *mostrar el catálogo*, *responder a todas horas*, o *perder ventas de noche*?'
    );
  }
  if (code === 'servicios') {
    return (
      'Perfecto' +
