/** Aceptación de propuesta: sí / dale / ok / me late / etc. */
LUNA.isAcceptProposal = function (text) {
  var t = LUNA.normMsg(text);
  if (!t || t.length > 80) return false;
  if (
    /^(dale|ok|okay|listo|de una|vamos|me late|perfecto|acepto|si|sí|va|hecho|cerramos|va que va|de una vez)$/i.test(
      t
    )
  )
    return true;
  if (
    /^(si|sí)\s*(quiero|dale|va|acepto|me late)?$/i.test(t) ||
    /si quiero|sí quiero|si dale|sí dale/i.test(t)
  )
    return true;
  if (
    /quiero (el )?(pack|propuesta)|vamos con (el )?(pack|propuesta)|me sirve|lo tomo|lo quiero|acepto (la )?propuesta|cerramos (el )?trato/i.test(
      t
    )
  )
    return true;
  return false;
};

