/** Eco del dolor + solución corta SIN tabla de precios */
LUNA.buildSolutionDesign = function (ctx) {
  ctx = ctx || {};
  var n = ctx.name ? ', ' + ctx.name : '';
  var code = ctx.rubro || (ctx.pc ? 'pcs' : '') || '';
  var hint = String(ctx.userHint || ctx.lastUser || '')
    .replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 110);
  var sol = LUNA.solutionForRubro(code);
  var why = '';
  if (code === 'pcs') {
    why = 'cotizas más rápido y atiendes lo repetido en WhatsApp; tú cierras lo técnico o la venta grande.';
  } else if (code === 'retail') {
    why = 'muestras productos claro y no pierdes chats de noche.';
  } else if (code === 'servicios') {
    why = 'generas confianza online y calificas quién escribe antes de que tú entres.';
  } else if (code === 'inmobiliaria') {
    why = 'filtras leads (zona/presupuesto/interés) y dejas de ahogarte en chats.';
  } else if (code === 'restaurante') {
    why = 'menú visible + WhatsApp para horarios y preguntas del local.';
  } else {
    why = 'alineamos web + WhatsApp a cómo te escriben hoy.';
  }
  var line = 'Va' + n + ' 👍\n\n';
  if (hint.length > 6) {
    line += 'Como me dijiste: _«' + hint + '»_\n\n';
  }
  line +=
    'Te propongo: *' +
    sol +
    '* — ' +
    why +
    '\n\n';
  if (ctx.email && String(ctx.email).includes('@')) {
    line += '¿Te dejo ya la *propuesta con números* aquí? Responde *sí* o dime qué cambiar.';
  } else {
    line += 'Si te parece, pégame tu *correo* y te dejo la *propuesta con números* en este chat.';
  }
  return line;
};

