const body = $json.body || $json || {};

// Fail closed: Chatwoot also emits outgoing agent/bot messages through the webhook.
// Only an explicitly incoming message may enter the chatbot.
const rawMessageType =
  body.message_type ??
  body.data?.message_type ??
  body.data?.message?.message_type ??
  body.data?.message?.message_type ??
  body.data?.message?.message_type ??
  body.message?.message_type ??
  body.message?.message?.message_type ??
  body.message?.message?.message_type ??
  body.message?.message?.message_type ??
  body.payload?.message_type ??
  body.payload?.message?.message_type;
const messageType = String(rawMessageType ?? '').trim().toLowerCase();
const sender =
  body.sender ??
  body.data?.sender ??
  body.data?.message?.sender ??
  body.data?.message?.sender ??
  body.data?.message?.sender ??
  body.message?.sender ??
  body.message?.message?.sender ??
  body.message?.message?.sender ??
  body.message?.message?.sender ??
  body.payload?.sender ??
  body.payload?.message?.sender ??
  body.payload?.message?.sender ??
  body.payload?.message?.sender ??
  {};
const senderType = String(sender.type ?? sender.kind ?? sender.role ?? '').trim().toLowerCase();
const eventName = String(
  body.event ??
  body.data?.event ??
  body.data?.message?.event ??
  body.data?.message?.event ??
  body.data?.message?.event ??
  body.message?.event ??
  body.message?.message?.event ??
  body.message?.message?.event ??
  body.message?.message?.event ??
  body.payload?.event ??
  body.payload?.message?.event ??
  body.payload?.message?.event ??
  body.payload?.message?.event ??
  ''
).trim().toLowerCase();
const explicitIncoming = messageType === 'incoming' || messageType === '0';
const explicitOutgoing =
  messageType === 'outgoing' ||
  messageType === '1' ||
  /outgoing|agent_bot|bot_message/.test(messageType);
const senderIsAgent =
  /^(agent|agent_bot|bot|assistant|user|team|team_member)$/.test(senderType) ||
  /agent|bot|assistant/.test(senderType);

if (eventName && eventName !== 'message_created') return [];
if (explicitOutgoing || senderIsAgent) return [];
// Fail closed: unknown message types are not inbound.
if (!explicitIncoming) return [];

const content = String(body.content || '').trim();
const attachments = body.attachments || body.content_attributes?.attachments || [];
const contentType = String(body.content_type || '').toLowerCase();
const hasMedia = (Array.isArray(attachments) && attachments.length > 0) || /audio|image|video|file|sticker|location/i.test(contentType);

// Whitelist heredada desactivada. Nunca guardar teléfonos personales en el workflow.
// Si se habilita en el futuro, la lista debe provenir de una credencial o variable segura.
const WHITELIST_ENABLED = false;
const ALLOWED_PHONES = [];

if (body.event && body.event !== 'message_created') return [];
if (!content && !hasMedia) return [];

