  for (const k of preferKeys) {
    if (obj[k] != null) collectPhones(obj[k], out, depth + 1);
  }
  // rutas típicas Chatwoot
  if (obj.sender) collectPhones(obj.sender, out, depth + 1);
  if (obj.meta?.sender) collectPhones(obj.meta.sender, out, depth + 1);
  if (obj.conversation?.meta?.sender) collectPhones(obj.conversation.meta.sender, out, depth + 1);
  if (obj.contact) collectPhones(obj.contact, out, depth + 1);
  if (obj.conversation?.contact_inbox) collectPhones(obj.conversation.contact_inbox, out, depth + 1);
  return out;
