  if (!notes.toLowerCase().includes(g.toLowerCase())) notes = notes ? notes + ' | ' + g : g;
}
notes = (notes ? notes + ' | ' : '') + `Score: ${score} | Etapa: ${stage} | Intent: ${i}`;

// human_required SOLO si pidió asesor (no por score alto)
const human_required =
  explicitHuman && !reactivate && !isReset
    ? 'true'
    : reactivate || isReset
      ? 'false'
      : stage === 'handoff' && !reactivate && !isReset
        ? 'true'
        : 'false';

let bot_muted = 'false';
if (reactivate || isReset) bot_muted = 'false';
else if (optOut) bot_muted = 'true'; // no molestar = no más mensajes del bot
else if (explicitHuman || stage === 'handoff') bot_muted = 'true';
else bot_muted = 'false';


function formatBogota(ms) {
  const d = new Date(ms);
  if (!Number.isFinite(d.getTime())) return '';
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/Bogota',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(d);
  const g = (t) => parts.find((p) => p.type === t)?.value || '';
  // DD/MM/YYYY HH:mm (hora Colombia)
  return g('day') + '/' + g('month') + '/' + g('year') + ' ' + g('hour') + ':' + g('minute');
}
function hoursFromNow(h) {
  return formatBogota(Date.now() + h * 60 * 60 * 1000);
}

// Follow-ups: 2h (suave) + 24h — no pisar enviados; cancelar en handoff/mute
const prevCount24 = Number(old.followup_count || 0) || 0;
const prevCount2h = Number(old.followup_2h_count || 0) || 0;
const MAX_24 = 2;
const MAX_2H = 1;

const prevSt2 = String(old.followup_2h_status || 'none').toLowerCase();
const prevSt24 = String(old.followup_status || 'none').toLowerCase();
const prevAt2 = old.followup_2h_at || '';
const prevAt24 = old.followup_at || '';

let followup_status = prevSt24 || 'none';
let followup_at = prevAt24 || '';
let followup_2h_status = prevSt2 || 'none';
let followup_2h_at = prevAt2 || '';

const cancelFu =
  bot_muted === 'true' ||
  human_required === 'true' ||
  stage === 'handoff' ||
  i === 'humano' ||
  i === 'opt_out' ||
  optOut ||
  isReset;

if (cancelFu) {
  followup_status = 'cancelled';
  followup_2h_status = 'cancelled';
  followup_at = '';
  followup_2h_at = '';
} else {
  // 2h: solo 1 vez; si ya sent/maxed no reabrir; si pending conservar fecha o empujar por actividad
  if (prevCount2h >= MAX_2H || prevSt2 === 'sent' || prevSt2 === 'maxed') {
    followup_2h_status = prevCount2h >= MAX_2H || prevSt2 === 'sent' ? (prevSt2 === 'sent' ? 'sent' : 'maxed') : 'maxed';
    followup_2h_at = '';
    if (prevSt2 === 'sent') followup_2h_status = 'sent';
  } else {
    followup_2h_status = 'pending';
    // cada mensaje del usuario empuja +2h (no molestar mientras habla)
    followup_2h_at = hoursFromNow(2);
  }

  // 24h: hasta 2; empujar mientras hable; no reabrir si maxed
  if (prevCount24 >= MAX_24 || prevSt24 === 'maxed') {
    followup_status = 'maxed';
    followup_at = '';
  } else if (prevSt24 === 'cancelled') {
    followup_status = 'pending';
    followup_at = hoursFromNow(24);
  } else {
    followup_status = 'pending';
    followup_at = hoursFromNow(24);
  }
}

// Nota privada a equipo si lead caliente (no handoff mudo)
const hasEmailNow = Boolean(data.email || data.known_email || r.known_email || r.email_this_turn);
const isProposal = String(data.proposal_requested || r.proposal_requested || '').toLowerCase() === 'true' ||
  String(data.proposal_send_candidate || r.proposal_send_candidate || '').toLowerCase() === 'true' ||
  String(data.proposal_delivery_status || r.proposal_delivery_status || '').toLowerCase() === 'sent';
// notify handoff always
const notify_team_private =
  status === 'caliente' ||
  score >= 70 ||
  human_required === 'true' ||
  hasEmailNow ||
  isProposal ||
  stage === 'handoff' ||
  i === 'humano'
    ? 'true'
    : 'false';

const biz = String(data.business_type || r.business_type || '');
const tagHints = [
  'luna-bot',
  status === 'caliente' || score >= 70 ? 'caliente' : score >= 40 ? 'tibio' : 'frio',
  /pc|hardware/i.test(biz) ? 'pc-hardware' : '',
  /retail|tienda|ropa/i.test(biz) ? 'retail' : '',
  /inmobil|arriendo/i.test(biz) ? 'inmobiliaria' : '',
  /restaurant|comida/i.test(biz) ? 'restaurante' : '',
  /servicio|consultor/i.test(biz) ? 'servicios' : '',
  /pack|chatbot|web/i.test(String(data.selected_solution || data.interested_service || '')) ? 'pack-interes' : '',
  hasEmailNow ? 'con-correo' : 'sin-correo',
  isProposal ? 'propuesta' : '',
  human_required === 'true' || stage === 'handoff' || i === 'humano' ? 'handoff' : '',
  (human_required === 'true' || i === 'humano') && typeof _openNow !== 'undefined'
    ? (_openNow ? 'en-horario' : 'fuera-horario')
    : '',
  String(data.opt_out || r.opt_out || '') === 'true' ? 'opt-out' : '',
  String(data.urgency || r.urgency || '') === 'ya' ? 'urgente' : '',
].filter(Boolean);

// private note handoff hours
function _bizOpenNow() {
  try {
    const fmt = new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/Bogota',
      weekday: 'short',
      hour: 'numeric',
      minute: 'numeric',
      hour12: false,
    });
    const parts = fmt.formatToParts(new Date());
    const map = {};
    for (const p of parts) map[p.type] = p.value;
    const dayMap = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
    const day = dayMap[String(map.weekday || '').toLowerCase()];
    const hour = Number(map.hour === '24' ? 0 : map.hour);
    const minute = Number(map.minute || 0);
    const mins = hour * 60 + minute;
    return day >= 1 && day <= 5 && mins >= 8 * 60 && mins < 18 * 60;
  } catch (e) {
    return true;
  }
}
const _openNow = _bizOpenNow();
const _hoursLabel = _openNow
  ? 'EN HORARIO (lun–vie 8:00–18:00 COT) — atender pronto'
  : 'FUERA DE HORARIO — el cliente NO debe esperar en línea; responder próximo hábil desde 8:00 COT';

const _nextAction =
  human_required === 'true' || i === 'humano'
    ? (_openNow ? 'Atender YA en este chat' : 'Programar respuesta en horario (8:00 COT)')
    : hasEmailNow
      ? 'Seguir propuesta / cierre por chat'
      : 'Pedir correo o calificar rubro';
const _biz = data.business_type || r.business_type || '—';
const _urg = data.urgency || r.urgency || '—';
const _rol = data.decision_role || r.decision_role || '—';
const _bud = data.budget_signal || r.budget_signal || '—';
const handoff_at =
  human_required === 'true' || stage === 'handoff' || i === 'humano'
    ? new Date().toISOString()
    : data.handoff_at || old.handoff_at || '';

// HANDOFF v2

// FASE2_BANT_NOTE — ficha completa para ops
const _bantBlock =
  `*BANT / ficha*\n` +
  `Urgencia: ${urgency || data.urgency || r.urgency || '—'}\n` +
  `Rol decisión: ${decision_role || data.decision_role || r.decision_role || '—'}\n` +
  `Presupuesto señal: ${budget_signal || data.budget_signal || r.budget_signal || '—'}\n` +
  `Ficha confirmada: ${String(data.ficha_confirmada || r.ficha_confirmada || 'false')}\n` +
  `Propuesta enviada: ${String(data.proposal_sent || r.proposal_sent || 'false')}\n` +
  `Propuesta aceptada: ${String(data.proposal_accepted || r.proposal_accepted || 'false')}\n` +
  `Sitio compartido: ${String(data.site_shared || r.site_shared || 'false')}\n` +
  `Rubro: ${data.business_type || r.business_type || '—'}\n`;

const private_note =
  `🔥 *Lead ${status.toUpperCase()} — Luna*\n\n` +
  (human_required === 'true' || stage === 'handoff' || i === 'humano'
    ? `⚠️ *HANDOFF HUMANO*\nHorario: *${_hoursLabel}*\nHandoff at: ${handoff_at}\n\n`
    : '') +
  `*Siguiente acción:* ${_nextAction}\n\n` +
  `Tags: ${tagHints.join(', ')}\n` +
  `Score: *${score}* | Etapa: ${stage} | Intent: ${i}\n\n` +
  _bantBlock + `\n*Contacto*\n` +
  `Nombre: ${data.client_name || data.known_name || r.known_name || '—'}\n` +
  `Email: ${data.email || data.known_email || r.known_email || '—'}\n` +
  `Tel: ${r.phone || data.phone || '—'}\n\n` +
  `*Negocio*\n` +
  `Rubro: ${_biz}\n` +
  `Solución: ${data.interested_service || data.selected_solution || r.selected_solution || '—'}\n` +
  `Urgencia: ${_urg} | Rol: ${_rol} | Presupuesto: ${_bud}\n\n` +
  `*Contexto*\n` +
  `Último msg: ${String(r.user_message || data.original_message || '—').slice(0, 220)}\n` +
  `Resumen: ${String(data.conversation_summary || r.conversation_summary || '—').slice(0, 280)}\n` +
  `Conv: ${r.conversation_id || ''}`;


// FASE3_METRICS — contadores de instancia (static; se reinician al redeploy)
try {
  const sd = $getWorkflowStaticData('global');
  if (!sd.luna_metrics) sd.luna_metrics = { day: '', proposals: 0, handoffs: 0, optouts: 0, messages: 0 };
  const dayKey = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
  if (sd.luna_metrics.day !== dayKey) {
    sd.luna_metrics = { day: dayKey, proposals: 0, handoffs: 0, optouts: 0, messages: 0 };
  }
  sd.luna_metrics.messages = (sd.luna_metrics.messages || 0) + 1;
  const _ps = String(data.proposal_sent || r.proposal_sent || '').toLowerCase() === 'true' ||
    String(data.proposal_delivery_status || r.proposal_delivery_status || '').toLowerCase() === 'sent';
  const _pa = String(data.proposal_accepted || r.proposal_accepted || '').toLowerCase() === 'true';
  if (_pa || (i === 'propuesta' && /acept|dale|sí quiero|si quiero/i.test(String(r.user_message || data.original_message || '')))) {
    sd.luna_metrics.proposals = (sd.luna_metrics.proposals || 0) + 1;
  } else if (_ps && String(data.proposal_sent || '') === 'true' && String(old.proposal_sent || '') !== 'true') {
    sd.luna_metrics.proposals = (sd.luna_metrics.proposals || 0) + 1;
  }
  if (human_required === 'true' || i === 'humano' || stage === 'handoff') {
    if (String(old.bot_muted || '') !== 'true') sd.luna_metrics.handoffs = (sd.luna_metrics.handoffs || 0) + 1;
  }
  if (typeof optOut !== 'undefined' && optOut) {
    sd.luna_metrics.optouts = (sd.luna_metrics.optouts || 0) + 1;
  }
  data._metrics_day = sd.luna_metrics.day;
  data._metrics_proposals = sd.luna_metrics.proposals;
  data._metrics_handoffs = sd.luna_metrics.handoffs;
  data._metrics_optouts = sd.luna_metrics.optouts;
  data._metrics_messages = sd.luna_metrics.messages;
} catch (e) {}

return [
  {
    json: {
      chatwoot_labels: typeof tagHints !== 'undefined' ? tagHints : ['luna-bot'],

      ...data,
      lead_status: status,
      notes,
      next_action: next,
      pipeline_stage: stage,
      last_intent: i,
      human_required,
      bot_muted,
      lead_score: score,
      handoff_at: typeof handoff_at !== 'undefined' ? handoff_at : '',
      next_action: typeof _nextAction !== 'undefined' ? _nextAction : data.next_action || '',
      opt_out: reactivate || isReset ? 'false' : typeof optOut !== 'undefined' && optOut ? 'true' : String(data.opt_out || r.opt_out || 'false'),
      urgency: typeof urgency !== 'undefined' ? urgency : '',
      decision_role: typeof decision_role !== 'undefined' ? decision_role : '',
      budget_signal: typeof budget_signal !== 'undefined' ? budget_signal : '',
      ficha_confirmada: String(data.ficha_confirmada || r.ficha_confirmada || 'false'),
      site_shared: String(data.site_shared || r.site_shared || 'false'),
      proposal_sent: String(data.proposal_sent || r.proposal_sent || 'false'),
      proposal_accepted: String(data.proposal_accepted || r.proposal_accepted || 'false'),
      business_type: data.business_type || r.business_type || '',
      final_reply: String(data.final_reply || data.ai_response || ''),
      sales_stage: stage,
      valid: true,
      conversation_summary: data.conversation_summary || r.conversation_summary || '',
      followup_at,
      followup_status,
      followup_count: String(prevCount24),
      followup_2h_at,
      followup_2h_status,
      followup_2h_count: String(prevCount2h),
      last_bot_at: formatBogota(Date.now()),
      notify_team_private,
      private_note,
      phone: r.phone || data.phone || '',
    },
  },
];

