// 25r — reset conservador del CRM.
// Limpia el contexto comercial, pero conserva identidad básica, opt-out y mute
// hasta que el usuario ejecute una reactivación explícita.
function safeNode(name) {
  try { return $(name).first().json || {}; } catch (e) { return {}; }
}
const r = safeNode('25 Sistema | Memoria + Contexto');
const bodyEnvelope = safeNode('01 Entrada | Webhook Chatwoot');
const body = bodyEnvelope.body || bodyEnvelope || {};
const truthy = (v) => v === true || v === 1 || String(v || '').toLowerCase() === 'true' || String(v || '') === '1';
const text = (v) => String(v == null ? '' : v).trim();
const conversationId = String(body.conversation?.id || r.conversation_id || '');
const phone = text(body.conversation?.meta?.sender?.phone_number || r.phone);
const row = safeNode('06 CRM | Buscar lead en Sheets');
const hasRow = row.row_number !== undefined && row.row_number !== null && text(row.row_number) !== '';
const now = new Date().toISOString();
const preserveOptOut = truthy(r.opt_out);
const preserveHuman = truthy(r.human_required);
const preserveMute = truthy(r.bot_muted);
const preserveHandoff = preserveHuman || preserveMute;
const preserveName = text(r.name);
const preserveHandoffAt = text(r.handoff_at);

try {
  const staticData = $getWorkflowStaticData('global');
  if (staticData.conversation_locks && conversationId) delete staticData.conversation_locks[conversationId];
  if (staticData.luna_proposal_requested && conversationId) delete staticData.luna_proposal_requested[conversationId];
  if (!staticData.luna_mem) staticData.luna_mem = {};
  if (conversationId) {
    delete staticData.luna_mem[conversationId];
    staticData.luna_mem[conversationId] = { reset_at: now, ignore_profile_name: true };
  }
} catch (e) {}

const pipelineStage = preserveOptOut ? 'cerrado' : preserveHandoff ? 'handoff' : 'nuevo';
const nextAction = preserveOptOut ? 'No contactar' : preserveHandoff ? 'Esperar asesor' : 'Completar descubrimiento';

return [{ json: {
  has_row: hasRow ? 'true' : 'false',
  row_number: hasRow ? String(row.row_number) : '',
  schema_version: '2.0',
  conversation_id: conversationId,
  phone,
  history: '[]',
  name: preserveName,
  // El correo se borra para que una propuesta nueva siempre requiera una
  // confirmación explícita posterior al reset.
  email: '',
  known_email: '',
  email_this_turn: '',
  pending_email: '',
  waiting_for_name: 'false',
  business_type: '',
  interested_service: '',
  lead_status: 'frio',
  notes: 'RESET comercial — contexto borrado; nombre, teléfono y controles conservados',
  last_message: text(body.content || 'reset'),
  last_ai_response: 'Memoria comercial borrada. Podemos empezar de nuevo.',
  updated_at: now,
  next_action: nextAction,
  appointment_date: '',
  budget: '',
  human_required: preserveHuman ? 'true' : 'false',
  project_goal: '',
  selected_solution: '',
  pipeline_stage: pipelineStage,
  last_intent: 'reset',
  missing_fields: preserveOptOut ? '' : 'business_type, project_goal',
  lead_score: '0',
  conversation_summary: '',
  followup_at: '',
  followup_status: 'none',
  followup_count: '0',
  last_bot_at: '',
  bot_muted: preserveMute ? 'true' : 'false',
  followup_2h_at: '',
  followup_2h_status: 'none',
  followup_2h_count: '0',
  opt_out: preserveOptOut ? 'true' : 'false',
  handoff_at: preserveHandoffAt,
  urgency: '',
  decision_role: '',
  budget_signal: '',
  ficha_confirmada: 'false',
  site_shared: 'false',
  proposal_sent: 'false',
  proposal_accepted: 'false',
  pain_point: '',
  current_process: '',
  impact: '',
  desired_outcome: '',
  discovery_urgency: '',
  discovery_depth: '0',
  discovery_done: 'false',
  recommended_solution: '',
  solution_confirmed: 'false',
  price_requested: 'false',
  proposal_requested: 'false',
  proposal_delivery_status: 'none',
  objection_code: '',
  handoff_reason: preserveHandoff ? text(r.handoff_reason) : '',
  appointment_status: '',
  appointment_timezone: '',
  appointment_event_id: '',
  appointment_confirmation_sent: 'false',
  final_reply: 'Listo ✅ Borré el contexto comercial de esta conversación.\n\nEmpezamos de cero.\n\n¿En qué te puedo ayudar? Puedes contarme tu negocio y qué quieres resolver.',
} }];

// No hay fila en Sheets: no hay nada que borrar.
// Pasamos el payload al mensaje de confirmación.
return [{ json: $json }];

// Prepara burbujas WhatsApp — propuestas enteras; resto se puede partir suave
function safe(name) {
  try { return $(name).first().json || {}; } catch (e) { return {}; }
}
const p = $json || {};
const r = safe('25 Sistema | Memoria + Contexto');
let text = String(p.final_reply || '').trim();
if (!text) return [];

// Register the outgoing text briefly so a Chatwoot/WhatsApp echo
// cannot re-enter the chatbot as a new inbound message.
try {
  const sd = $getWorkflowStaticData('global');
  const conversationId = String(
    p.conversation_id ||
    r.conversation_id ||
    p.body?.conversation?.id ||
    r.body?.conversation?.id ||
    ''
  ).trim();
  const normalizeEcho = (value) => String(value || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
  const hashEcho = (value) => {
    let h = 2166136261;
    const s = normalizeEcho(value);
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h += (h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24);
    }
    return (h >>> 0).toString(16);
  };
  if (conversationId) {
    const at = Date.now();
    sd.outbound_echoes = sd.outbound_echoes || {};
    sd.outbound_echo_prefixes = sd.outbound_echo_prefixes || {};
    sd.outbound_echoes[conversationId + ':' + hashEcho(text)] = at;
    const prefix = normalizeEcho(text).slice(0, 80);
    if (prefix.length >= 24) {
      const previous = Array.isArray(sd.outbound_echo_prefixes[conversationId])
        ? sd.outbound_echo_prefixes[conversationId]
        : [];
      sd.outbound_echo_prefixes[conversationId] = [
        ...previous,
        { prefix, at },
      ].slice(-12);
    }
  }
} catch (e) {}

const isProposal =
  /Propuesta Luenio|borrador de propuesta|Inversión de referencia/i.test(text) ||
  p.intent === 'datos_consulta' ||
  p.pipeline_stage === 'propuesta';

let part1 = text;
let part2 = '';

// No partir propuestas ni handoff ni ficha
const keepWhole =
  isProposal ||
  /HANDOFF|asesor humano|Confirmo tu ficha|Confirmo que anoté/i.test(text) ||
  text.length <= 900;

if (!keepWhole && text.length > 560) {
  const parts = text.split(/\n\n+/);
  if (parts.length >= 2) {
    const mid = Math.ceil(parts.length / 2);
    part1 = parts.slice(0, mid).join('\n\n').trim();
    part2 = parts.slice(mid).join('\n\n').trim();
    // evitar part2 minúscula
    if (part2.length < 40) {
      part1 = text;
      part2 = '';
    }
  }
}

const sendMedia = p.send_first_contact_media === 'true';

return [{
  json: {
