// 14a — Contrato comercial LUNA v2.
// Determinista, sin precios y basado únicamente en mensajes del usuario.
function nodeJson(name) {
  try { return $(name).first().json || {}; } catch (e) { return {}; }
}
const source = { ...nodeJson('25 Sistema | Memoria + Contexto'), ...($json || {}) };
const rawMessage = String(source.user_message || source.last_message || '').replace(/\s+/g, ' ').trim();
const text = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
const lower = (v) => text(v).toLowerCase();
const truthy = (v) => v === true || v === 1 || String(v || '').toLowerCase() === 'true' || String(v || '') === '1';
const validEmail = (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text(v));
const clean = (v, max = 180) => text(v).replace(/[«»"']/g, '').replace(/[.!?]+$/g, '').slice(0, max).trim();
const userHistory = Array.isArray(source.history_for_llm)
  ? source.history_for_llm.filter((x) => String(x && x.role || '').toLowerCase() === 'user').map((x) => text(x.content)).filter(Boolean)
  : [];
const messages = [...userHistory, rawMessage].filter(Boolean);
const allUserText = messages.join(' \n ');
const currentLower = lower(rawMessage);
const reset = /^\s*(?:reset|reset total|reiniciar|resetear|empezar de cero|borrar memoria)\s*$/i.test(rawMessage);
const activate = /activar\s+luna|reactivar\s+luna|volver\s+con\s+luna/i.test(currentLower);
const optOutNow = /no molestar|no me escribas|no quiero (?:m[aá]s )?mensajes|dejen de escribir|\bstop\b|\bbaja\b|unsubscribe/i.test(currentLower);
const handoffNow = /\b(asesor|humano|persona real|agente)\b/i.test(currentLower);

function find(pattern) {
  for (const value of [...messages].reverse()) if (pattern.test(value)) return value;
  return '';
}
function segment(raw, startPattern, stopPattern, max = 180) {
  const value = text(raw);
  if (!value) return '';
  const start = value.search(startPattern);
  let out = start >= 0 ? value.slice(start) : value;
  if (stopPattern) {
    const stop = out.search(stopPattern);
    if (stop > 0) out = out.slice(0, stop);
  }
  return clean(out, max);
}
function businessFrom(value) {
  const t = lower(value);
  if (/\bpc\b|\bpcs\b|computador|hardware|perif[eé]rico|armar\s*pc|vendo\s*pcs?|partes\s*de\s*pc/.test(t)) return 'venta de PCs / hardware';
  if (/inmobil|arriendo|apartament|casa en venta|finca ra[ií]z|propiedades/.test(t)) return 'inmobiliaria';
  if (/restaurant|comida|men[uú] digital|pedidos|delivery|cafeter[ií]a/.test(t)) return 'restaurante / alimentos';
  if (/tienda|retail|ropa|zapatos|cat[aá]logo de productos|vendo productos|e-?commerce/.test(t)) return 'tienda / retail';
  if (/cl[ií]nica|dental|est[eé]tica|abogad|taller|peluquer|consultor|servicio profesional/.test(t)) return 'negocio de servicios';
  return '';
}
function explicitSolution(value) {
  const t = lower(value);
  if (/asesor|humano|persona real|hablar con alguien/.test(t)) return 'asesor';
  if (/\b(pack|ambos|los dos|web\s*(?:\+|y)\s*(?:chatbot|whatsapp)|chatbot\s*(?:\+|y)\s*web)\b/.test(t)) return 'pack_web_chatbot';
  if (/\bsolo\s+chatbot\b|\bnecesito\s+un\s+chatbot\b|\bquiero\s+un\s+chatbot\b|\bchatbot\s+para\s+whatsapp\b/.test(t)) return 'chatbot_whatsapp_ia';
  if (/\bsolo\s+(?:la\s+)?web\b|\bnecesito\s+una\s+(?:web|p[aá]gina)\b|\bquiero\s+(?:una\s+)?(?:web|p[aá]gina)\b|\bcat[aá]logo\s+web\b/.test(t)) return 'web_catalogo';
  return '';
}
function objection(value) {
  const t = lower(value);
  if (/muy caro|est[aá]\s+caro|costoso|no me alcanza/.test(t)) return 'price_high';
  if (/lo voy a pensar|dej(?:a|ame)\s+pensarlo/.test(t)) return 'need_to_think';
  if (/solo (?:quiero )?informaci[oó]n/.test(t)) return 'only_information';
  if (/no tengo presupuesto|sin presupuesto/.test(t)) return 'no_budget';
  if (/ya tengo web/.test(t)) return 'already_has_web';
  if (/ya tengo (?:un )?bot|ya tengo chatbot/.test(t)) return 'already_has_bot';
  if (/solo cotizaci[oó]n|solo cotizar/.test(t)) return 'wants_quote_only';
  if (/no tengo tiempo|estoy ocupado|hablamos luego/.test(t)) return 'no_time';
  if (/a la medida|personaliz|caso particular|alcance especial/.test(t)) return 'custom_scope';
  if (/asesor|humano|persona real/.test(t)) return 'wants_human';
  return '';
}

const sourceWasReset = /^(?:reset|reset total)$/i.test(text(source.last_intent)) || /reset total|memoria borrada/i.test(text(source.notes));
const persisted = (key) => reset || sourceWasReset ? '' : text(source[key]);
const business = reset ? '' : persisted('business_type') || businessFrom(allUserText);
const goalRaw = reset ? '' : find(/\b(necesito|quiero|busco|me interesa)\b.{0,140}\b(chatbot|web|p[aá]gina|cat[aá]logo|automatiz|responder|responde|ventas)\b/i);
const goal = reset ? '' : segment(goalRaw, /\b(necesito|quiero|busco|me interesa)\b/i, /\s+(?:y|pero)\s+(?=(?:necesito|quiero|busco|hoy|actualmente)\b)/i) || persisted('project_goal');
const painRaw = reset ? '' : find(/(?:pierdo|perdemos|se pierden|se nos van|no respondo|no respondemos|no alcanzo|no alcanzamos|se acumulan|no doy abasto|tardo en responder|fuera de horario|me cuesta responder|problema|dolor|me preocupa|no conviert)/i);
const pain = reset ? '' : text(source.pain_point) || segment(painRaw, /(?:pierdo|perdemos|se pierden|se nos van|no respondo|no respondemos|no alcanzo|no alcanzamos|se acumulan|no doy abasto|tardo en responder|fuera de horario|me cuesta responder|problema|dolor|me preocupa|no conviert)/i, /\s+y\s+(?=(?:hoy|actualmente|ahora|atendemos|atiendo|respondemos|respondo)\b)/i);
const currentRaw = reset ? '' : find(/(?:actualmente|hoy\s+(?:atendemos|atiendo|lo hacemos|respondemos|respondo)|atendemos|atenci[oó]n manual|manual|a mano|por whatsapp|en whatsapp|excel|instagram|facebook|sin sistema|no tenemos|me encargo yo|una persona)/i);
const current = reset ? '' : text(source.current_process) || segment(currentRaw, /(?:hoy|actualmente|atendemos|atiendo|lo hacemos|respondemos|respondo|atenci[oó]n manual|manual|a mano|por whatsapp|en whatsapp|excel|instagram|facebook|sin sistema|no tenemos|me encargo yo|una persona)/i, /\s+(?:y|pero)\s+(?=(?:quiero|necesito|busco|me interesa|porque)\b)/i);
const impactRaw = reset ? '' : find(/(?:pierdo ventas|perdemos ventas|se pierden ventas|se nos van|se acumulan|no alcanzo|no alcanzamos|clientes|ventas|tiempo|demora|fuera de horario|oportunidades)/i);
const impact = reset ? '' : text(source.impact) || segment(impactRaw, /(?:pierdo ventas|perdemos ventas|se pierden ventas|se nos van|se acumulan|no alcanzo|no alcanzamos|clientes|ventas|tiempo|demora|fuera de horario|oportunidades)/i, /\s+y\s+(?=(?:hoy|actualmente|ahora|atendemos|atiendo|respondemos|respondo)\b)/i);
